import os, pwd, sys
from pathlib import Path
AUTOCUE_ROOT_ENV = "VDJ_AUTOCUE_ROOT"
_AUTOCUE_MODULES = ("vdj_database_safety", "vdj_cuer", "compute_thread_limits")

def _real_home() -> Path:  # not Path.home(): pw_bleed overrides HOME
    try:
        return Path(pwd.getpwuid(os.getuid()).pw_dir)
    except (KeyError, OSError):
        return Path.home()

def autocue_root() -> Path:
    raw = os.environ.get(AUTOCUE_ROOT_ENV, "").strip()
    root = (Path(raw).expanduser() if raw else _real_home() / "src" / "vdj-station").resolve()
    if not (root / "vdj_database_safety.py").is_file() or not (root / "vdj_cuer" / "__init__.py").is_file():
        raise RuntimeError(f"AutoCue root {root} has no vdj_database_safety.py + vdj_cuer/; set {AUTOCUE_ROOT_ENV}")
    return root

def _assert_not_shadowed(root: Path) -> None:
    for name in _AUTOCUE_MODULES:
        origin = getattr(sys.modules.get(name), "__file__", None)
        if origin and not Path(origin).resolve().is_relative_to(root):
            raise RuntimeError(f"{name} imported from {origin}, not AutoCue root {root}; restart via start_8788*.sh")

def ensure_autocue_on_path() -> Path:
    root = autocue_root()
    entry = str(root)
    if sys.path[:1] != [entry]:
        while entry in sys.path:
            sys.path.remove(entry)
        sys.path.insert(0, entry)
    _assert_not_shadowed(root)
    return root

